import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </SkeletonProvider>
  </CSPProvider>
);

export const ShowcaseSurface = ({ children }: { children?: ReactNode }) => (
  <div
    data-slot="component-preview"
    className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
  >
    {children}
  </div>
);

import { Spinner } from "@/registry/erbium/ui/spinner";

const SpinnerDemo = () => <Spinner />;

export default SpinnerDemo;

import { Icon } from "@/registry/erbium/ui/icon";

import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
  InputGroupTextarea,
} from "@/registry/erbium/ui/input-group";

const SpinnerInputGroup = () => (
  <div className="grid w-full gap-group sm:grid-cols-2">
    {(["ltr", "rtl"] as const).map((direction) => (
      <div key={direction} dir={direction} className="flex w-full max-w-md flex-col gap-group">
        <InputGroup loading>
          <InputGroupInput
            placeholder={direction === "rtl" ? "ارسال پیام..." : "Send a message..."}
            disabled
          />
        </InputGroup>
        <InputGroup loading>
          <InputGroupTextarea
            placeholder={direction === "rtl" ? "ارسال پیام..." : "Send a message..."}
            disabled
          />
          <InputGroupAddon align="block-end">
            {direction === "rtl" ? "در حال اعتبارسنجی..." : "Validating..."}
            <InputGroupButton className="ms-auto" variant="default">
              <Icon name="arrow-up-01" />
              <span className="sr-only">{direction === "rtl" ? "ارسال" : "Send"}</span>
            </InputGroupButton>
          </InputGroupAddon>
        </InputGroup>
      </div>
    ))}
  </div>
);

export default SpinnerInputGroup;

import { Spinner } from "@/registry/erbium/ui/spinner";

const SpinnerSize = () => (
  <div className="flex items-center gap-section">
    <Spinner size="xs" />
    <Spinner size="sm" />
    <Spinner size="default" />
    <Spinner size="lg" />
    <Spinner size="xl" />
  </div>
);

export default SpinnerSize;

