import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { Spinner } from "@/registry/erbium/ui/spinner";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import { Spinner } from \"@/registry/erbium/ui/spinner\";\nimport type * as React from \"react\";\n\nconst Example = (args: React.ComponentProps<typeof Spinner>) => <Spinner {...args} />;\n\nexport default Example;\n";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/spinner-demo\";\n\nconst Example = () => <Demo />;\n\nexport default Example;\n";

import SizeExample from "./variants/size";

const SizeSource = "import ExampleSpinnerSize from \"../examples/spinner-size\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <ExampleSpinnerSize />\n  </div>\n);\n\nexport default Example;\n";

import ButtonExample from "./variants/button";

const ButtonSource = "import ExampleSpinnerButton from \"../examples/spinner-button\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <ExampleSpinnerButton />\n  </div>\n);\n\nexport default Example;\n";

import BadgeExample from "./variants/badge";

const BadgeSource = "import ExampleSpinnerBadge from \"../examples/spinner-badge\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <ExampleSpinnerBadge />\n  </div>\n);\n\nexport default Example;\n";

import InputGroupExample from "./variants/input-group";

const InputGroupSource = "import ExampleSpinnerInputGroup from \"../examples/spinner-input-group\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <ExampleSpinnerInputGroup />\n  </div>\n);\n\nexport default Example;\n";

const meta = {
  component: Spinner,
  parameters: {
    docs: {
      description: {
        component: "**Import:** `@/registry/erbium/ui/spinner`\n\n## Usage\n\n```tsx\nimport { Spinner } from \"@/registry/erbium/ui/spinner\";\n```\n\n```tsx\n<Spinner />\n```\n\n## Loading\n\nPrefer a [Skeleton](/docs/components/skeleton) for content whose shape is known, and keep already-known content visible while it is enhanced. Use a [Logo Loader](/docs/components/logo-loader) for broader waits without a content layout, such as navigation or workspace preparation. Use a spinner for localized activity, especially a pending action or status; an empty state represents the absence of results, not loading.\n\nUse standalone `Spinner` for independent loading indicators. Use `Button loading`, `Badge loading`, or `InputGroup loading` inside controls so the component owns placement and sizing. `StatefulButton` centers its spinner while replacing the label.\n\nSpinners beside labels belong at the inline start: left in LTR and right in RTL. Inherit `dir` from the page or set it on a containing element. Loading APIs do not expose a spinner alignment option.",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof Spinner>;

export default { ...meta, title: "Components/Spinner",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<typeof Spinner> = {
  argTypes: {
    size: { control: "select", options: ["xs", "sm", "default", "lg", "xl"] },
    "aria-label": { control: "text" },
  },
  args: { size: "lg" },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const Size: Story = {
  parameters: {
    docs: {
      description: { story: "Use the `size` prop to change the size of the spinner." },
      source: { code: SizeSource },
    },
  },
  render: SizeExample,
};

export const Button: Story = {
  parameters: {
    docs: {
      description: { story: "Use `Button loading` to show a spinner at the inline start (left in LTR, right in RTL) and block activation. `InputGroupButton` inherits the same API. Icon-only buttons center the spinner." },
      source: { code: ButtonSource },
    },
  },
  render: ButtonExample,
};

export const Badge: Story = {
  parameters: {
    docs: {
      description: { story: "Use `Badge loading` to show a spinner at the inline start: left in LTR and right in RTL. The badge manages placement and sizing automatically." },
      source: { code: BadgeSource },
    },
  },
  render: BadgeExample,
};

export const InputGroup: Story = {
  parameters: {
    docs: {
      description: { story: "Set `loading` on `InputGroup` to show a spinner at the inline start (left in LTR, right in RTL) and set `aria-busy`. Keep status text in a block addon when needed. Loading does not disable editing; set `disabled` on the input separately when appropriate." },
      source: { code: InputGroupSource },
    },
  },
  render: InputGroupExample,
};

